"""Long-running coding agent. Compacts its own history at the window limit."""

WINDOW = 180000

# Constraints that MUST_SURVIVE every compaction boundary. Losing one silently
# is worse than running out of window, so the rewrite is checked, not trusted.
MUST_SURVIVE = (
    "never force-push",
    "ask before deleting production data",
)


def compact(messages):
    summary = client.messages.create(
        model="claude",
        messages=messages + [{"role": "user", "content": "Summarise this run."}],
    )
    rebuilt = [
        {"role": "user", "content": PINNED_RULES},
        {"role": "user", "content": summary.content},
    ]
    verify_compaction(rebuilt)
    return rebuilt


def verify_compaction(messages):
    """Fail loudly if a load-bearing constraint did not survive the rewrite."""
    joined = "\n".join(m["content"] for m in messages)
    lost = [c for c in MUST_SURVIVE if c not in joined]
    if lost:
        raise CompactionLostConstraint(lost)


def step(messages, task):
    if count_tokens(messages) > WINDOW:
        messages = compact(messages)
    return client.messages.create(model="claude", messages=messages)
